content.text:
Now the main server. This is the big one. Let me write it carefully.

Key routes and idempotency logic.

Also note `import { ... } from 'node:sqlite'` unused in seed — I imported DatabaseSync but don't use it. Remove to avoid lint noise (harmless though). I'll leave; actually unused import is fine but let me keep clean later if time.

Now index.mjs.

```js
import express from 'express';
import path from 'node:path';
import crypto from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import { openDb, localDisplay, localDate, nowUtcIso, tx } from './db.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const DB_PATH = process.env.DB_PATH ?? path.join(ROOT, 'data', 'app.db');
const PORT = Number(process.env.PORT ?? 3000);
const db = openDb(DB_PATH);
const app = express();
app.use(express.json());
```

Actor middleware. Then routes.

Helper: getActor(req) → row join tenants.

Let me write serial generation:
```js
function nextSerial(tenantId) {
  const t = db.prepare('SELECT code, next_serial FROM tenants WHERE id=?').get(tenantId);
  const n = t.next_serial;
  db.prepare('UPDATE tenants SET next_serial=? WHERE id=?').run(n+1, tenantId);
  return `CERT-${t.code}-${String(n).padStart(6,'0')}`;
}
```
Called inside transaction.

List building shared SQL for list + export.

```js
function buildQuery({tenantId, search, sort, order}) { ... returns {sql, params} }
```
Sort map:
issued_local_date → 'c.issued_local_date'
learner_name → 'l.name'
serial_no → 'c.serial_no'
Default issued_local_date desc.

Order must be ASC|DESC uppercase.

Search: `(l.name LIKE ? OR c.serial_no LIKE ?)`.

Export: ORDER BY same + ', c.id ASC'.

Now idempotency.

```js
function sha(s){return crypto.createHash('sha256').update(s).digest('hex');}
```

Bulk issue flow:

```js
app.post('/api/certificates/bulk-issue', async (req,res) => {
  const actor = req.actor;
  const courseId = req.body?.courseId;
  if (typeof courseId !== 'string' || !courseId) return badRequest(res,'courseId is required');
  const key = req.get('idempotency-key');
  if (!key) return res.status(400).json({error:{code:'idempotency_key_required', message:'Idempotency-Key header is required'}});

  // A1: 先校验课程归属，再动任何写入 → 跨租户不留任何副作用
  const course = db.prepare('SELECT id,title FROM courses WHERE id=? AND tenant_id=?').get(courseId, actor.tenant_id);
  if (!course) return res.status(404).json({error:{code:'course_not_found',message:'Course not found'}});

  const fingerprint = sha(JSON.stringify({courseId}));
  const claim = claimOperation(actor.tenant_id, key, fingerprint, courseId);
  if (claim.kind === 'mismatch') return res.status(409).json({error:{code:'idempotency_key_reuse', message:'Idempotency-Key already used with a different request payload'}});
  if (claim.kind === 'replay') return res.status(claim.httpStatus).set('Idempotent-Replay','true').json(claim.response);
  if (claim.kind === 'pending') {
    const done = await waitForOperation(actor.tenant_id, key, 30000);
    if (!done) return res.status(409).json({error:{code:'operation_in_progress',...}});
    return res.status(200).set('Idempotent-Replay','true').json(done);
  }
  // owner: do the work
  let response;
  try { response = performBulkIssue(actor, course); }
  catch (e) { db.prepare('DELETE FROM idempotency_operations WHERE tenant_id=? AND idem_key=?').run(actor.tenant_id,key); throw e; }
  return res.status(200).json(response);
});
```

claimOperation:
```js
function claimOperation(tenantId, key, fingerprint, courseId){
  const row = db.prepare('SELECT * FROM idempotency_operations WHERE tenant_id=? AND idem_key=?').get(tenantId,key);
  if (row) {
    if (row.fingerprint !== fingerprint) return {kind:'mismatch'};
    if (row.status === 'COMPLETED') return {kind:'replay', httpStatus: row.http_status ?? 200, response: JSON.parse(row.response_json)};
    return {kind:'pending'};
  }
  try { db.prepare('INSERT INTO idempotency_operations (tenant_id,idem_key,fingerprint,course_id,status,created_at) VALUES (?,?,?,?,?,?)').run(tenantId,key,fingerprint,courseId,'IN_PROGRESS',nowUtcIso()); }
  catch(e){ // race: another request inserted first
    return claimOperation(tenantId,key,fingerprint,courseId); // re-read
  }
  return {kind:'owner'};
}
```
Insert is auto-committed (no explicit tx) → visible immediately. ✓

waitForOperation polls.

performBulkIssue:
```js
function performBulkIssue(actor, course){
  const tz = actor.timezone;
  const now = nowUtcIso();
  const localD = localDate(now, tz), localDisp = localDisplay(now, tz);
  // all enrollments of course in tenant
  const enrs = db.prepare(`SELECT e.id, e.status, e.learner_id, l.name AS learner_name
     FROM enrollments e JOIN learners l ON l.id=e.learner_id
     WHERE e.tenant_id=? AND e.course_id=? ORDER BY l.name, e.id`).all(actor.tenant_id, course.id);
  const certOf = new Map(db.prepare(`SELECT learner_id FROM certificates WHERE tenant_id=? AND course_id=?`).all(actor.tenant_id,course.id).map(r=>[r.learner_id,true]));
  const outcomes = []; let issued=0, skipped=0, failed=0;
  tx(db, ()=>{
    const insCert = db.prepare(`INSERT INTO certificates (id,tenant_id,course_id,learner_id,enrollment_id,serial_no,issued_at_utc,issued_local_date,issued_local_display,status) VALUES (?,?,?,?,?,?,?,?,?,'ACTIVE')`);
    const insAudit = db.prepare(`INSERT INTO audit_events (tenant_id,certificate_id,action,actor_email,at_utc,metadata_json) VALUES (?,?,'ISSUED',?,?,?)`);
    for (const e of enrs) {
      if (certOf.has(e.learner_id)) { outcomes.push({learnerId:e.learner_id, learnerName:e.learner_name, status:'skipped', reason:'already_certified'}); skipped++; continue; }
      if (e.status !== 'completed') { outcomes.push({...status:'skipped', reason:'incomplete_enrollment'}); skipped++; continue; }
      try {
        const certId = `cert-${crypto.randomUUID()}`;
        const serial = nextSerial(actor.tenant_id);
        insCert.run(certId, actor.tenant_id, course.id, e.learner_id, e.id, serial, now, localD, localDisp);
        insAudit.run(actor.tenant_id, certId, actor.email, now, JSON.stringify({source:'bulk-issue', idempotencyKey:...}));
        outcomes.push({learnerId:e.learner_id, learnerName:e.learner_name, status:'issued', serialNumber:serial, certificateId:certId});
        issued++;
      } catch(err){ outcomes.push({...status:'failed', reason:'issue_failed'}); failed++; }
    }
    const response = {operationId:..., courseId, courseTitle, summary:{total:enrs.length, issued, skipped, failed}, outcomes, issuedAtUtc: now};
    db.prepare('UPDATE idempotency_operations SET status=?, http_status=?, response_json=?, completed_at=? WHERE tenant_id=? AND idem_key=?')
      .run('COMPLETED',200,JSON.stringify(response),now,actor.tenant_id,key);
  });
}
```
Need key passed in. And operationId = key? Use `op-${key}` or the idem key itself. Store operationId = key (it identifies the logical operation). Use `operationId: key`.

Hmm careful: failed sub-insert inside a transaction that later throws → whole tx rollback. Attempting INSERT that violates unique inside try/catch would abort? SQLite constraint violation aborts the statement, not the transaction (unless ON CONFLICT ROLLBACK). So catching and continuing is fine. But safer: pre-check already done via certOf. Fine.

But: if an inner statement fails, transaction still usable (default conflict resolution ABORT rolls back the statement only). OK.

Important: the unique index ux_cert_once will throw if duplicate — pre-checked.

Also: perf of `nextSerial` — one update per cert, fine.

Revoke:
```js
app.post('/api/certificates/:id/revoke', (req,res)=>{
  const cert = db.prepare('SELECT ... WHERE id=? AND tenant_id=?').get(id, tenant);
  if (!cert) 404
  const now = nowUtcIso();
  let changed = 0;
  tx(db, ()=>{
    changed = db.prepare(`UPDATE certificates SET status='REVOKED', revoked_at_utc=?, revoked_by=? WHERE id=? AND tenant_id=? AND status='ACTIVE'`).run(now, actor.email, id, tenant).changes;
    if (changed === 1) db.prepare(`INSERT INTO audit_events (tenant_id,certificate_id,action,actor_email,at_utc,metadata_json) VALUES (?,?,'REVOKED',?,?,?)`).run(...);
  });
  const fresh = getCert(...);
  res.json({...serialize(fresh), alreadyRevoked: changed===0});
