function buildListQuery({ tenantId, search, sort, order, limit, offset }) {
  const col = SORTABLE[sort] ?? SORTABLE.issued_local_date;
  const dir = String(order).toUpperCase() === 'ASC' ? 'ASC' : 'DESC';
  const q = (search ?? '').trim();
  const where = ['c.tenant_id = ?'];
  const params = [tenantId];
  if (q) { where.push('(l.name LIKE ? OR c.serial_no LIKE ?)'); params.push(`%${q}%`, `%${q}%`); }
  const whereSql = where.join(' AND ');
  const sql = `${CERT_SELECT} WHERE ${whereSql} ORDER BY ${col} ${dir}, c.id ASC LIMIT ? OFFSET ?`;
  const countSql = `SELECT COUNT(*) AS n FROM certificates c JOIN learners l ON l.id=c.learner_id WHERE ${whereSql}`;
  return { sql, countSql, params, dir, col };
}
