app.post('/api/certificates/bulk-issue', async (req, res) => {
  try {
    const actor = req.actor;
    const courseId = req.body?.courseId;
    if (typeof courseId !== 'string' || !courseId.trim())
      return res.status(400).json({ error: { code: 'validation_error', message: 'courseId is required' } });
    const idemKey = req.get('idempotency-key');
    if (!idemKey) return res.status(400).json({ error: { code: 'idempotency_key_required', message: 'Idempotency-Key header is required' } });

    // A1_4: 先校验课程归属，任何写操作之前
    const course = db.prepare('SELECT id, title FROM courses WHERE id = ? AND tenant_id = ?').get(courseId, actor.tenant_id);
    if (!course) return res.status(404).json({ error: { code: 'course_not_found', message: 'Course not found' } });

    const fingerprint = sha(JSON.stringify({ courseId }));
    const claim = claimOperation(actor.tenant_id, idemKey, fingerprint, courseId);

    if (claim.kind === 'mismatch') return res.status(409).json({ error: { code: 'idempotency_key_reuse', message: 'Idempotency-Key was already used with a different request payload' } });
    if (claim.kind === 'replay') return res.status(claim.httpStatus).set('Idempotent-Replay', 'true').json(claim.response);
    if (claim.kind === 'pending') {
      const done = await waitForOperation(actor.tenant_id, idemKey);
      if (!done) return res.status(409).json({ error: { code: 'operation_in_progress', message: 'A concurrent operation with this key is still running' } });
      return res.status(done.httpStatus).set('Idempotent-Replay', 'true').json(done.response);
    }

    let response;
    try { response = runBulkIssue(actor, course, idemKey); }
    catch (err) {
      db.prepare('DELETE FROM idempotency_operations WHERE tenant_id=? AND idem_key=?').run(actor.tenant_id, idemKey);
      throw err;
    }
    return res.status(200).json(response);
  } catch (err) { next500(res, err); }
});
