const old=\"if (!fs.existsSync('node_modules')) run('npm', ['install', '--no-audit', '--no-fund'], '① 安装依赖');\";
if(!s.includes(old)){console.error('anchor missing');process.exit(1);}
const neu=\`if (!fs.existsSync('node_modules')) {
  // 有 lockfile 时用 npm ci：可复现，且不会像 npm install 那样因 postinstall 补 hasInstallScript 而弄脏工作树
  const args = fs.existsSync('package-lock.json')
    ? ['ci', '--no-audit', '--no-fund']
    : ['install', '--no-audit', '--no-fund'];
  run('npm', args, '① 安装依赖');
}\`;
s=s.replace(old,neu); fs.writeFileSync(p,s); console.log('patched start.mjs');
" && git add package-lock.json scripts/start.mjs && git commit -q -m "fix(B1): 提交含 postinstall 元数据的 lockfile，并用 npm ci 保证可复现且不弄脏工作树" && git log --oneline -1","description":"Use npm ci and commit corrected lockfile"}

